),
src AS (SELECT scdb_docket_id, scdb_case_id, era, term::smallint AS term, decided_on::date AS decided_on, us_cite, docket FROM raw),

scdb_src AS (
  SELECT s.scdb_docket_id, s.term, s.decided_on,
         CASE WHEN s.us_cite ~* '^\s*[0-9]+\s*U\.?\s*S\.?\s+[0-9]+' THEN regexp_replace(s.us_cite, '^\s*0*([0-9]+)\s*[Uu]\.?\s*[Ss]\.?\s+0*([0-9]+).*$', '\1us\2') END AS us_key,
         nullif(regexp_replace(regexp_replace(lower(coalesce(s.docket, '')), '^\s*nos?\.?\s*', ''), '[^a-z0-9]', '', 'g'), '') AS docket_key
  FROM src s
),
jv AS (
  SELECT lc.id, lc.supreme_court_term AS term, lc.decided_on,
         nullif(regexp_replace(regexp_replace(lower(coalesce(lc.docket_number, '')), '^\s*nos?\.?\s*', ''), '[^a-z0-9]', '', 'g'), '') AS docket_key,
         CASE WHEN lc.official_citation ~* '^\s*[0-9]+\s*U\.?\s*S\.?\s+[0-9]+' THEN regexp_replace(lc.official_citation, '^\s*0*([0-9]+)\s*[Uu]\.?\s*[Ss]\.?\s+0*([0-9]+).*$', '\1us\2') END AS us_key
  FROM legal_case lc
  JOIN court ct ON ct.id = lc.court_id
  WHERE lc.supreme_court_term IS NOT NULL OR lower(ct.provider_court_id) = 'scotus'
),
jv_us AS (
  SELECT id, us_key FROM jv WHERE us_key IS NOT NULL
  UNION
  SELECT cci.case_id, cci.citation_key FROM case_citation_identity cci JOIN jv ON jv.id = cci.case_id
  WHERE cci.citation_key ~ '^[0-9]+us[0-9]+$'
),
m_us AS (
  SELECT s.scdb_docket_id,
         count(DISTINCT jv.id) AS n,
         count(DISTINCT jv.id) FILTER (WHERE jv.docket_key = s.docket_key) AS n_docket,
         (array_agg(DISTINCT jv.id))[1] AS any_id,
         (array_agg(DISTINCT jv.id) FILTER (WHERE jv.docket_key = s.docket_key))[1] AS docket_id
  FROM scdb_src s JOIN jv_us u ON u.us_key = s.us_key JOIN jv ON jv.id = u.id
  GROUP BY s.scdb_docket_id
),
m_date AS (
  SELECT s.scdb_docket_id, count(DISTINCT jv.id) AS n, (array_agg(DISTINCT jv.id))[1] AS any_id
  FROM scdb_src s JOIN jv ON jv.docket_key = s.docket_key AND jv.decided_on = s.decided_on
  GROUP BY s.scdb_docket_id
),
m_term AS (
  SELECT s.scdb_docket_id, count(DISTINCT jv.id) AS n, (array_agg(DISTINCT jv.id))[1] AS any_id
  FROM scdb_src s JOIN jv ON jv.docket_key = s.docket_key AND jv.term = s.term
  GROUP BY s.scdb_docket_id
),
scdb_match AS (
  SELECT s.scdb_docket_id,
         CASE WHEN u.n = 1 THEN u.any_id WHEN u.n_docket = 1 THEN u.docket_id
              WHEN d.n = 1 THEN d.any_id WHEN t.n = 1 THEN t.any_id END AS legal_case_id,
         CASE WHEN u.n = 1 OR u.n_docket = 1 THEN 'us_cite'
              WHEN d.n = 1 THEN 'docket_and_date' WHEN t.n = 1 THEN 'docket_and_term' END AS match_method,
         CASE WHEN u.n = 1 OR u.n_docket = 1 THEN u.n
              WHEN d.n = 1 THEN d.n WHEN t.n = 1 THEN t.n
              ELSE greatest(coalesce(u.n, 0), coalesce(d.n, 0), coalesce(t.n, 0)) END::smallint AS match_candidates
  FROM scdb_src s
  LEFT JOIN m_us u USING (scdb_docket_id)
  LEFT JOIN m_date d USING (scdb_docket_id)
  LEFT JOIN m_term t USING (scdb_docket_id)
),
per_case AS (
  SELECT s.scdb_case_id, min(s.era) AS era, min(s.term) AS term,
         bool_or(m.legal_case_id IS NOT NULL) AS matched,
         (array_agg(m.match_method ORDER BY s.scdb_docket_id) FILTER (WHERE m.legal_case_id IS NOT NULL))[1] AS method,
         bool_or(m.legal_case_id IS NULL AND m.match_candidates > 1) AS ambiguous
  FROM src s JOIN scdb_match m USING (scdb_docket_id)
  GROUP BY s.scdb_case_id
),
dockets AS (
  SELECT s.era, count(*) AS dockets, count(m.legal_case_id) AS dockets_matched, count(DISTINCT m.legal_case_id) AS distinct_jurvio_cases
  FROM src s JOIN scdb_match m USING (scdb_docket_id) GROUP BY ROLLUP (s.era)
)
SELECT 'era' AS dim, coalesce(era, 'all') AS bucket, count(*) AS scdb_cases, count(*) FILTER (WHERE matched) AS matched,
       round(100.0 * count(*) FILTER (WHERE matched) / count(*), 2) AS match_pct,
       count(*) FILTER (WHERE method = 'us_cite') AS by_us_cite,
       count(*) FILTER (WHERE method = 'docket_and_date') AS by_docket_date,
       count(*) FILTER (WHERE method = 'docket_and_term') AS by_docket_term,
       count(*) FILTER (WHERE NOT matched AND ambiguous) AS ambiguous_unmatched
FROM per_case GROUP BY ROLLUP (era)
UNION ALL
SELECT 'decade', (term / 10 * 10)::text, count(*), count(*) FILTER (WHERE matched),
       round(100.0 * count(*) FILTER (WHERE matched) / count(*), 2),
       count(*) FILTER (WHERE method = 'us_cite'), count(*) FILTER (WHERE method = 'docket_and_date'),
       count(*) FILTER (WHERE method = 'docket_and_term'), count(*) FILTER (WHERE NOT matched AND ambiguous)
FROM per_case GROUP BY term / 10 * 10
UNION ALL
SELECT 'recent_term', term::text, count(*), count(*) FILTER (WHERE matched),
       round(100.0 * count(*) FILTER (WHERE matched) / count(*), 2),
       count(*) FILTER (WHERE method = 'us_cite'), count(*) FILTER (WHERE method = 'docket_and_date'),
       count(*) FILTER (WHERE method = 'docket_and_term'), count(*) FILTER (WHERE NOT matched AND ambiguous)
FROM per_case WHERE term >= 2015 GROUP BY term
UNION ALL
SELECT 'dockets', coalesce(era, 'all'), dockets, dockets_matched, round(100.0 * dockets_matched / dockets, 2), distinct_jurvio_cases, NULL, NULL, NULL
FROM dockets
ORDER BY 1, 2;
